<template>
  <section :class="b()">
    <header :class="b('toolbar')">
      <div :class="b('toolbar-left')">
        <el-button v-if="showUpload" type="primary" :disabled="isDisabled" @click="selectFiles">
          <el-icon><el-icon-upload /></el-icon>
          上传文件
        </el-button>
        <el-button :disabled="isDisabled" @click="openCreateFolder">
          <el-icon><el-icon-folder-add /></el-icon>
          新建文件夹
        </el-button>
        <el-button :disabled="isDisabled || !selectedFile" @click="openMoveDialog">
          移动
        </el-button>
        <el-button :disabled="isDisabled || !selectedFile" @click="openRenameDialog">
          重命名
        </el-button>
        <el-button type="danger" :disabled="isDisabled || !selectedFile" @click="removeSelectedFile">
          删除
        </el-button>
      </div>
      <el-input
        v-model="keyword"
        clearable
        :class="b('search')"
        placeholder="搜索当前文件夹"
      >
        <template #prefix><el-icon><el-icon-search /></el-icon></template>
      </el-input>
    </header>

    <input
      ref="fileInput"
      :accept="accept"
      :multiple="multiple"
      type="file"
      :disabled="isDisabled"
      :class="b('native-input')"
      @change="handleNativeFileChange"
    />

    <div :class="b('workspace')" :style="workspaceStyle">
      <aside :class="b('folders')">
        <div :class="b('folder-title')">文件夹</div>
        <el-scrollbar>
          <div
            :class="[b('root'), { 'is-active': activeFolderId === rootFolderId }]"
            role="button"
            tabindex="0"
            @click="selectFolder(rootFolderId)"
            @keyup.enter="selectFolder(rootFolderId)"
          >
            <el-icon><el-icon-folder-opened /></el-icon>
            <span>{{ rootLabel }}</span>
            <em>{{ rootFilesCount }}</em>
            <el-dropdown :class="b('root-menu')" :disabled="isDisabled" trigger="click" @command="handleRootCommand" @click.stop>
              <el-button text circle :disabled="isDisabled" aria-label="根目录操作菜单" @click.stop>
                <el-icon><el-icon-more-filled /></el-icon>
              </el-button>
              <template #dropdown>
                <el-dropdown-menu>
                  <el-dropdown-item command="create" :disabled="isDisabled">新建文件夹</el-dropdown-item>
                </el-dropdown-menu>
              </template>
            </el-dropdown>
          </div>
          <el-tree
            ref="folderTree"
            :data="folderTree"
            :props="treeProps"
            node-key="id"
            highlight-current
            :current-node-key="activeFolderId"
            :expand-on-click-node="false"
            @node-click="handleFolderClick"
          >
            <template #default="{ data }">
              <span :class="b('folder-node')">
                <span>{{ data.name }}</span>
                <em>{{ getFolderFileCount(data.id) }}</em>
                <el-dropdown :class="b('folder-menu')" :disabled="isDisabled" trigger="click" @command="handleFolderCommand($event, data)" @click.stop>
                  <el-button text circle :disabled="isDisabled" :aria-label="`${data.name} 操作菜单`" @click.stop>
                    <el-icon><el-icon-more-filled /></el-icon>
                  </el-button>
                  <template #dropdown>
                    <el-dropdown-menu>
                      <el-dropdown-item command="create" :disabled="isDisabled">新建子文件夹</el-dropdown-item>
                      <el-dropdown-item command="rename" :disabled="isDisabled">重命名</el-dropdown-item>
                      <el-dropdown-item command="remove" divided :disabled="isDisabled || !canRemoveFolder(data)">删除</el-dropdown-item>
                    </el-dropdown-menu>
                  </template>
                </el-dropdown>
              </span>
            </template>
          </el-tree>
        </el-scrollbar>
      </aside>

      <main :class="b('files')">
        <div :class="b('files-header')">
          <span>{{ activeFolderName }}</span>
          <small>{{ visibleFiles.length }} 个文件</small>
        </div>
        <el-scrollbar :class="b('files-scroll')">
          <el-empty v-if="!visibleFiles.length" description="当前文件夹暂无文件" />
          <div v-else :class="b('grid')">
            <div
              v-for="file in visibleFiles"
              :key="file.id"
              :class="[b('file'), { 'is-active': file.id === selectedFileId }]"
              role="button"
              tabindex="0"
              @click="selectFile(file)"
              @dblclick="previewFile(file)"
              @keyup.enter="previewFile(file)"
            >
              <el-dropdown :class="b('file-menu')" :disabled="isDisabled" trigger="click" @command="handleFileCommand($event, file)" @click.stop>
                <el-button
                  text
                  circle
                  :disabled="isDisabled"
                  :aria-label="`${file.name} 操作菜单`"
                  @click.stop
                >
                  <el-icon><el-icon-more-filled /></el-icon>
                </el-button>
                <template #dropdown>
                  <el-dropdown-menu>
                    <el-dropdown-item command="preview">预览</el-dropdown-item>
                    <el-dropdown-item command="move" :disabled="isDisabled">移动</el-dropdown-item>
                    <el-dropdown-item command="rename" :disabled="isDisabled">重命名</el-dropdown-item>
                    <el-dropdown-item command="remove" divided :disabled="isDisabled">删除</el-dropdown-item>
                  </el-dropdown-menu>
                </template>
              </el-dropdown>
              <span :class="b('file-icon')">
                <el-icon v-if="getFileKind(file) === 'image'"><el-icon-picture /></el-icon>
                <el-icon v-else-if="getFileKind(file) === 'video'"><el-icon-video-play /></el-icon>
                <el-icon v-else-if="getFileKind(file) === 'audio'"><el-icon-headset /></el-icon>
                <el-icon v-else-if="getFileKind(file) === 'pdf'"><el-icon-document /></el-icon>
                <el-icon v-else><el-icon-files /></el-icon>
              </span>
              <span :class="b('file-name')" :title="file.name">{{ file.name }}</span>
              <small>{{ formatSize(file.size) || getFileExtension(file).toUpperCase() || '文件' }}</small>
              <span v-if="file.status === 'uploading'" :class="b('file-status')">上传中</span>
              <span v-else-if="file.status === 'error'" :class="[b('file-status'), 'is-error']">上传失败</span>
            </div>
          </div>
        </el-scrollbar>
      </main>

      <aside v-if="showPreview" :class="b('preview')">
        <header v-if="selectedFile" :class="b('preview-toolbar')">
          <div :class="b('preview-meta')">
            <span :class="b('preview-name')">{{ selectedFile.name }}</span>
            <span v-if="selectedFile.size" :class="b('preview-size')">{{ formatSize(selectedFile.size) }}</span>
          </div>
          <el-button v-if="downloadable" text type="primary" @click="downloadSelected">
            <el-icon><el-icon-download /></el-icon>
            下载
          </el-button>
        </header>
        <div :class="b('preview-content')" :style="previewContentStyle">
          <el-empty v-if="!selectedFile" description="请选择文件进行预览" />

          <el-image
            v-else-if="getFileKind(selectedFile) === 'image'"
            :src="selectedFile.url"
            :preview-src-list="[selectedFile.url]"
            fit="contain"
            :class="b('preview-image')"
            @error="handlePreviewError"
          />

          <video
            v-else-if="getFileKind(selectedFile) === 'video'"
            :src="selectedFile.url"
            controls
            preload="metadata"
            :class="b('preview-media')"
            @error="handlePreviewError"
          >当前浏览器不支持视频预览。</video>

          <audio
            v-else-if="getFileKind(selectedFile) === 'audio'"
            :src="selectedFile.url"
            controls
            preload="metadata"
            :class="b('preview-audio')"
            @error="handlePreviewError"
          >当前浏览器不支持音频预览。</audio>

          <iframe
            v-else-if="getFileKind(selectedFile) === 'pdf'"
            :src="selectedFile.url"
            :title="selectedFile.name"
            :class="b('preview-iframe')"
          ></iframe>

          <div v-else-if="getFileKind(selectedFile) === 'text'" :class="b('preview-text')">
            <el-skeleton v-if="textLoading" animated :rows="8" />
            <el-result v-else-if="textError" icon="error" title="文本预览失败" :sub-title="textError">
              <template #extra>
                <el-button v-if="downloadable" type="primary" @click="downloadSelected">下载文件</el-button>
              </template>
            </el-result>
            <pre v-else>{{ textContent }}</pre>
          </div>

          <el-result v-else icon="info" title="暂不支持在线预览">
            <template #sub-title><span>{{ selectedFile.name }} 可下载后在本地打开。</span></template>
            <template #extra>
              <el-button v-if="downloadable" type="primary" @click="downloadSelected">下载文件</el-button>
            </template>
          </el-result>
        </div>
      </aside>
    </div>

    <el-dialog v-model="folderDialogVisible" :title="folderDialogTitle" width="400px" append-to-body>
      <el-form @submit.prevent>
        <el-form-item label="文件夹名称" :error="folderDialogError">
          <el-input v-model="folderName" maxlength="50" show-word-limit @keyup.enter="saveFolder" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="folderDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="saveFolder">确定</el-button>
      </template>
    </el-dialog>

    <el-dialog v-model="folderDeleteDialogVisible" title="删除文件夹" width="400px" append-to-body>
      <p>确定删除文件夹“{{ folderToDelete ? folderToDelete.name : '' }}”吗？</p>
      <template #footer>
        <el-button @click="folderDeleteDialogVisible = false">取消</el-button>
        <el-button type="danger" @click="removeFolder">删除</el-button>
      </template>
    </el-dialog>

    <el-dialog v-model="renameDialogVisible" title="重命名文件" width="400px" append-to-body>
      <el-form @submit.prevent>
        <el-form-item label="文件名称" :error="renameDialogError">
          <el-input v-model="renameValue" maxlength="100" show-word-limit @keyup.enter="renameFile" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="renameDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="renameFile">确定</el-button>
      </template>
    </el-dialog>

    <el-dialog v-model="moveDialogVisible" title="移动文件" width="400px" append-to-body>
      <el-form @submit.prevent>
        <el-form-item label="目标文件夹">
          <el-select v-model="targetFolderId" filterable placeholder="选择文件夹">
            <el-option :label="rootLabel" :value="rootFolderId" />
            <el-option
              v-for="folder in localFolders"
              :key="folder.id"
              :label="getFolderPath(folder.id)"
              :value="folder.id"
            />
          </el-select>
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="moveDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="moveFile">确定</el-button>
      </template>
    </el-dialog>
  </section>
</template>

<script>
import create from "core/create";

const ROOT_FOLDER_ID = "__avue_root__";
const IMAGE_EXTENSIONS = ["bmp", "gif", "jpeg", "jpg", "png", "svg", "webp"];
const VIDEO_EXTENSIONS = ["m4v", "mov", "mp4", "ogv", "webm"];
const AUDIO_EXTENSIONS = ["aac", "flac", "m4a", "mp3", "oga", "ogg", "wav"];
const TEXT_EXTENSIONS = ["csv", "css", "html", "htm", "js", "json", "log", "md", "sql", "text", "ts", "txt", "xml", "yaml", "yml"];

export default create({
  name: "file-manager",
  props: {
    modelValue: {
      type: Array,
      default: () => [],
    },
    folders: {
      type: Array,
      default: () => [],
    },
    rootLabel: {
      type: String,
      default: "全部文件",
    },
    height: {
      type: [Number, String],
      default: 560,
    },
    accept: {
      type: String,
      default: "",
    },
    multiple: {
      type: Boolean,
      default: true,
    },
    maxSize: {
      type: Number,
      default: 0,
    },
    showUpload: {
      type: Boolean,
      default: true,
    },
    showPreview: {
      type: Boolean,
      default: true,
    },
    download: {
      type: Boolean,
      default: true,
    },
    disabled: {
      type: Boolean,
      default: false,
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    uploadRequest: Function,
  },
  emits: [
    "update:modelValue",
    "update:folders",
    "change",
    "select",
    "preview",
    "download",
    "upload",
    "remove",
    "error",
    "folder-change",
    "folder-create",
    "folder-rename",
    "folder-remove",
  ],
  data() {
    return {
      rootFolderId: ROOT_FOLDER_ID,
      localFiles: this.normalizeFiles(this.modelValue),
      localFolders: this.normalizeFolders(this.folders),
      activeFolderId: ROOT_FOLDER_ID,
      selectedFileId: "",
      keyword: "",
      idSeed: 0,
      folderDialogVisible: false,
      folderDialogError: "",
      folderName: "",
      folderDialogMode: "create",
      folderTargetId: ROOT_FOLDER_ID,
      folderDeleteDialogVisible: false,
      folderToDelete: null,
      renameDialogVisible: false,
      renameDialogError: "",
      renameValue: "",
      moveDialogVisible: false,
      targetFolderId: ROOT_FOLDER_ID,
      textContent: "",
      textError: "",
      textLoading: false,
      requestSeed: 0,
      requestController: null,
    };
  },
  computed: {
    isDisabled() {
      return this.disabled || this.readonly;
    },
    treeProps() {
      return { label: "name", children: "children" };
    },
    folderTree() {
      const nodes = {};
      const root = [];
      this.localFolders.forEach((folder) => {
        nodes[folder.id] = { ...folder, children: [] };
      });
      Object.values(nodes).forEach((folder) => {
        if (folder.parentId && nodes[folder.parentId]) {
          nodes[folder.parentId].children.push(folder);
        } else {
          root.push(folder);
        }
      });
      return root;
    },
    activeFolderName() {
      if (this.activeFolderId === ROOT_FOLDER_ID) return this.rootLabel;
      return (this.localFolders.find((folder) => folder.id === this.activeFolderId) || {}).name || this.rootLabel;
    },
    folderDialogTitle() {
      return this.folderDialogMode === "rename" ? "重命名文件夹" : "新建文件夹";
    },
    rootFilesCount() {
      return this.localFiles.filter((file) => file.folderId === ROOT_FOLDER_ID).length;
    },
    visibleFiles() {
      const keyword = this.keyword.trim().toLowerCase();
      return this.localFiles.filter((file) => {
        const sameFolder = file.folderId === this.activeFolderId;
        return sameFolder && (!keyword || file.name.toLowerCase().includes(keyword));
      });
    },
    selectedFile() {
      return this.localFiles.find((file) => file.id === this.selectedFileId) || null;
    },
    workspaceStyle() {
      const height = typeof this.height === "number" ? `${this.height}px` : this.height;
      return { minHeight: height };
    },
    previewHeight() {
      if (typeof this.height === "number") return Math.max(this.height - 54, 280);
      return this.height;
    },
    previewContentStyle() {
      const height = typeof this.previewHeight === "number" ? `${this.previewHeight}px` : this.previewHeight;
      return { minHeight: height };
    },
    downloadable() {
      return this.download && this.selectedFile && Boolean(this.selectedFile.url || this.selectedFile.downloadUrl);
    },
  },
  watch: {
    modelValue: {
      deep: true,
      handler(value) {
        this.syncFiles(value);
      },
    },
    folders: {
      deep: true,
      handler(value) {
        this.localFolders = this.normalizeFolders(value);
        if (this.activeFolderId !== ROOT_FOLDER_ID && !this.localFolders.some((folder) => folder.id === this.activeFolderId)) {
          this.selectFolder(ROOT_FOLDER_ID);
        }
      },
    },
    selectedFile: {
      immediate: true,
      handler(file) {
        this.loadTextContent(file);
      },
    },
  },
  beforeUnmount() {
    this.abortTextRequest();
    this.localFiles.forEach((file) => this.revokeObjectUrl(file));
  },
  methods: {
    createLocalId(prefix) {
      const seed = Number(this.idSeed) || 0;
      this.idSeed = seed + 1;
      return `${prefix}_${Date.now()}_${this.idSeed}`;
    },
    normalizeFiles(files) {
      const previousFiles = Array.isArray(this.localFiles) ? this.localFiles : [];
      return (Array.isArray(files) ? files : []).map((file) => {
        const value = file || {};
        const id = value.id || value.uid || this.createLocalId("file");
        const previous = previousFiles.find((item) => item.id === id && item.url === value.url);
        return {
          ...value,
          id,
          name: value.name || this.getFileName(value.url) || "未命名文件",
          url: value.url || value.downloadUrl || "",
          folderId: value.folderId || ROOT_FOLDER_ID,
          status: value.status || "success",
          _objectUrl: previous && previous._objectUrl,
        };
      });
    },
    normalizeFolders(folders) {
      const result = [];
      const append = (items, parentId = "") => {
        (Array.isArray(items) ? items : []).forEach((folder) => {
          const value = folder || {};
          const id = value.id || this.createLocalId("folder");
          result.push({
            ...value,
            id,
            name: value.name || "未命名文件夹",
            parentId: value.parentId || parentId || "",
          });
          if (value.children) append(value.children, id);
        });
      };
      append(folders);
      return result;
    },
    syncFiles(files) {
      const nextFiles = this.normalizeFiles(files);
      this.localFiles.forEach((file) => {
        if (!nextFiles.some((next) => next.id === file.id && next.url === file.url)) {
          this.revokeObjectUrl(file);
        }
      });
      this.localFiles = nextFiles;
      if (this.selectedFileId && !this.selectedFile) this.selectedFileId = "";
    },
    toExternalFile(file) {
      const { _objectUrl, ...value } = file;
      return { ...value };
    },
    emitFiles() {
      const files = this.localFiles.map((file) => this.toExternalFile(file));
      this.$emit("update:modelValue", files);
      this.$emit("change", files);
    },
    emitFolders() {
      const folders = this.localFolders.map(({ children, ...folder }) => ({ ...folder }));
      this.$emit("update:folders", folders);
    },
    selectFolder(id) {
      this.activeFolderId = id;
      this.selectedFileId = "";
      this.$emit("folder-change", id);
      this.$nextTick(() => {
        if (this.$refs.folderTree && id !== ROOT_FOLDER_ID) this.$refs.folderTree.setCurrentKey(id);
      });
    },
    handleFolderClick(folder) {
      this.selectFolder(folder.id);
    },
    handleRootCommand(command) {
      if (command === "create") this.openCreateFolder(ROOT_FOLDER_ID);
    },
    handleFolderCommand(command, folder) {
      this.selectFolder(folder.id);
      if (command === "create") {
        this.openCreateFolder(folder.id);
      } else if (command === "rename") {
        this.openRenameFolder(folder);
      } else if (command === "remove") {
        this.openRemoveFolder(folder);
      }
    },
    getFolderFileCount(folderId) {
      return this.localFiles.filter((file) => file.folderId === folderId).length;
    },
    getFolderPath(folderId) {
      const path = [];
      let folder = this.localFolders.find((item) => item.id === folderId);
      const visited = new Set();
      while (folder && !visited.has(folder.id)) {
        visited.add(folder.id);
        path.unshift(folder.name);
        folder = this.localFolders.find((item) => item.id === folder.parentId);
      }
      return path.join(" / ");
    },
    selectFiles() {
      if (this.isDisabled || !this.$refs.fileInput) return;
      this.$refs.fileInput.click();
    },
    async handleNativeFileChange(event) {
      const files = Array.from(event.target.files || []);
      event.target.value = "";
      for (const file of files) {
        await this.addFile(file);
      }
    },
    async addFile(rawFile) {
      if (this.maxSize > 0 && rawFile.size > this.maxSize * 1024 * 1024) {
        const error = new Error(`${rawFile.name} 超过 ${this.maxSize}MB 限制`);
        this.$emit("error", error, rawFile);
        return;
      }

      const objectUrl = typeof URL !== "undefined" && URL.createObjectURL ? URL.createObjectURL(rawFile) : "";
      const entry = {
        id: this.createLocalId("file"),
        name: rawFile.name,
        size: rawFile.size,
        type: rawFile.type,
        url: objectUrl,
        folderId: this.activeFolderId,
        status: this.uploadRequest ? "uploading" : "success",
        _objectUrl: objectUrl,
      };
      this.localFiles.push(entry);
      this.selectedFileId = entry.id;
      this.emitFiles();
      this.$emit("upload", rawFile, this.toExternalFile(entry));

      if (typeof this.uploadRequest !== "function") return;
      try {
        const result = await this.uploadRequest(rawFile, {
          folderId: this.activeFolderId,
          file: this.toExternalFile(entry),
        });
        const data = typeof result === "string" ? { url: result } : (result || {});
        const target = this.localFiles.find((file) => file.id === entry.id);
        if (!target) return;
        if (data.url && data.url !== target.url) this.revokeObjectUrl(target);
        Object.assign(target, data, { status: data.status || "success", _objectUrl: data.url ? "" : target._objectUrl });
        this.emitFiles();
      } catch (error) {
        const target = this.localFiles.find((file) => file.id === entry.id);
        if (target) {
          target.status = "error";
          target.errorMessage = error.message || "上传失败";
          this.emitFiles();
        }
        this.$emit("error", error, rawFile);
      }
    },
    revokeObjectUrl(file) {
      if (file && file._objectUrl && typeof URL !== "undefined" && URL.revokeObjectURL) {
        URL.revokeObjectURL(file._objectUrl);
        file._objectUrl = "";
      }
    },
    selectFile(file) {
      this.selectedFileId = file.id;
      this.$emit("select", this.toExternalFile(file));
    },
    previewFile(file) {
      this.selectFile(file);
      this.$emit("preview", this.toExternalFile(file));
    },
    handleFileCommand(command, file) {
      this.selectFile(file);
      if (command === "preview") {
        this.previewFile(file);
      } else if (command === "move") {
        this.openMoveDialog();
      } else if (command === "rename") {
        this.openRenameDialog();
      } else if (command === "remove") {
        this.removeSelectedFile();
      }
    },
    removeSelectedFile() {
      if (!this.selectedFile || this.isDisabled) return;
      const file = this.selectedFile;
      this.localFiles = this.localFiles.filter((item) => item.id !== file.id);
      this.revokeObjectUrl(file);
      this.selectedFileId = "";
      this.emitFiles();
      this.$emit("remove", this.toExternalFile(file));
    },
    canRemoveFolder(folder) {
      if (!folder || !folder.id) return false;
      const hasChildren = this.localFolders.some((item) => item.parentId === folder.id);
      const hasFiles = this.localFiles.some((file) => file.folderId === folder.id);
      return !hasChildren && !hasFiles;
    },
    openCreateFolder(parentId = this.activeFolderId) {
      if (this.isDisabled) return;
      this.folderDialogMode = "create";
      this.folderTargetId = parentId || ROOT_FOLDER_ID;
      this.folderName = "";
      this.folderDialogError = "";
      this.folderDialogVisible = true;
    },
    openRenameFolder(folder) {
      if (!folder || this.isDisabled) return;
      this.folderDialogMode = "rename";
      this.folderTargetId = folder.id;
      this.folderName = folder.name;
      this.folderDialogError = "";
      this.folderDialogVisible = true;
    },
    saveFolder() {
      const name = this.folderName.trim();
      if (!name) {
        this.folderDialogError = "请输入文件夹名称";
        return;
      }
      const target = this.localFolders.find((folder) => folder.id === this.folderTargetId);
      const parentId = this.folderDialogMode === "rename"
        ? (target && target.parentId) || ""
        : (this.folderTargetId === ROOT_FOLDER_ID ? "" : this.folderTargetId);
      const duplicated = this.localFolders.some((folder) =>
        folder.id !== this.folderTargetId && folder.parentId === parentId && folder.name === name
      );
      if (duplicated) {
        this.folderDialogError = "同一层级下已存在同名文件夹";
        return;
      }
      if (this.folderDialogMode === "rename") {
        if (!target) return;
        target.name = name;
        this.folderDialogVisible = false;
        this.emitFolders();
        this.$emit("folder-rename", { ...target });
        return;
      }
      const folder = { id: this.createLocalId("folder"), name, parentId };
      this.localFolders.push(folder);
      this.folderDialogVisible = false;
      this.emitFolders();
      this.$emit("folder-create", { ...folder });
      this.selectFolder(folder.id);
    },
    openRemoveFolder(folder) {
      if (this.isDisabled || !this.canRemoveFolder(folder)) return;
      this.folderToDelete = folder;
      this.folderDeleteDialogVisible = true;
    },
    removeFolder() {
      const folder = this.folderToDelete;
      if (!folder || !this.canRemoveFolder(folder)) return;
      const nextFolderId = folder.parentId || ROOT_FOLDER_ID;
      this.localFolders = this.localFolders.filter((item) => item.id !== folder.id);
      this.folderDeleteDialogVisible = false;
      this.folderToDelete = null;
      this.emitFolders();
      this.$emit("folder-remove", { ...folder });
      if (this.activeFolderId === folder.id) this.selectFolder(nextFolderId);
    },
    openRenameDialog() {
      if (!this.selectedFile || this.isDisabled) return;
      this.renameValue = this.selectedFile.name;
      this.renameDialogError = "";
      this.renameDialogVisible = true;
    },
    renameFile() {
      const name = this.renameValue.trim();
      if (!name) {
        this.renameDialogError = "请输入文件名称";
        return;
      }
      const duplicated = this.localFiles.some((file) => file.id !== this.selectedFile.id && file.folderId === this.selectedFile.folderId && file.name === name);
      if (duplicated) {
        this.renameDialogError = "当前文件夹已存在同名文件";
        return;
      }
      this.selectedFile.name = name;
      this.renameDialogVisible = false;
      this.emitFiles();
    },
    openMoveDialog() {
      if (!this.selectedFile || this.isDisabled) return;
      this.targetFolderId = this.selectedFile.folderId || ROOT_FOLDER_ID;
      this.moveDialogVisible = true;
    },
    moveFile() {
      if (!this.selectedFile) return;
      const fileId = this.selectedFile.id;
      this.selectedFile.folderId = this.targetFolderId;
      this.moveDialogVisible = false;
      this.emitFiles();
      this.selectFolder(this.targetFolderId);
      this.selectedFileId = fileId;
    },
    getFileName(url) {
      if (!url) return "";
      return url.split("?")[0].split("/").pop() || "";
    },
    getFileExtension(file) {
      const name = (file && (file.name || file.url)) || "";
      const extension = name.split("?")[0].split(".").pop();
      return extension && extension !== name ? extension.toLowerCase() : "";
    },
    getFileKind(file) {
      const type = String((file && file.type) || "").toLowerCase();
      const extension = this.getFileExtension(file);
      if (type.startsWith("image/") || IMAGE_EXTENSIONS.includes(extension)) return "image";
      if (type.startsWith("video/") || VIDEO_EXTENSIONS.includes(extension)) return "video";
      if (type.startsWith("audio/") || AUDIO_EXTENSIONS.includes(extension)) return "audio";
      if (type === "application/pdf" || extension === "pdf") return "pdf";
      if (type.startsWith("text/") || TEXT_EXTENSIONS.includes(extension)) return "text";
      return "file";
    },
    formatSize(size) {
      const value = Number(size);
      if (!Number.isFinite(value) || value < 0) return "";
      if (value < 1024) return `${value} B`;
      if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`;
      if (value < 1024 * 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)} MB`;
      return `${(value / 1024 / 1024 / 1024).toFixed(1)} GB`;
    },
    abortTextRequest() {
      if (this.requestController) {
        this.requestController.abort();
        this.requestController = null;
      }
    },
    async loadTextContent(file) {
      this.abortTextRequest();
      this.textContent = "";
      this.textError = "";
      this.textLoading = false;

      if (!file || this.getFileKind(file) !== "text") return;
      if (file.content !== undefined && file.content !== null) {
        this.textContent = String(file.content);
        return;
      }
      if (!file.url || typeof fetch !== "function") return;

      const requestId = ++this.requestSeed;
      const controller = new AbortController();
      this.requestController = controller;
      this.textLoading = true;

      try {
        const response = await fetch(file.url, { signal: controller.signal });
        if (!response.ok) throw new Error(`请求失败（${response.status}）`);
        const content = await response.text();
        if (requestId !== this.requestSeed) return;
        this.textContent = content;
      } catch (error) {
        if (error.name === "AbortError" || requestId !== this.requestSeed) return;
        this.textError = error.message || "无法读取文件内容";
        this.$emit("error", error, file);
      } finally {
        if (requestId === this.requestSeed) {
          this.textLoading = false;
          this.requestController = null;
        }
      }
    },
    downloadSelected() {
      if (!this.selectedFile || !this.downloadable) return;
      const link = document.createElement("a");
      link.href = this.selectedFile.downloadUrl || this.selectedFile.url;
      link.download = this.selectedFile.name || "";
      link.rel = "noopener";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      this.$emit("download", this.toExternalFile(this.selectedFile));
    },
    handlePreviewError(error) {
      this.$emit("error", error, this.selectedFile ? this.toExternalFile(this.selectedFile) : null);
    },
  },
});
</script>
